<?php
namespace App\Services;use App\Core\Database;use PDO;use RuntimeException;
class LaboratoryService
{
 public function create(array $d,array $files,int $env,int $by):int{return Database::transaction(function(PDO $db)use($d,$files,$env,$by){$animal=(int)($d['animal_id']??0);$type=(int)($d['tipo_examen_id']??0);if(!$animal||!$type)throw new RuntimeException('Paciente y tipo de examen son obligatorios.');$s=$db->prepare('SELECT 1 FROM animales WHERE id=:a AND entorno_id=:e AND deleted_at IS NULL');$s->execute(['a'=>$animal,'e'=>$env]);if(!$s->fetchColumn())throw new RuntimeException('Paciente no válido.');$eventType=(int)$db->query("SELECT id FROM tipos_evento_clinico WHERE codigo='LABORATORIO' LIMIT 1")->fetchColumn();$date=$this->dt($d['fecha_solicitud']??null);$s=$db->prepare('INSERT INTO eventos_clinicos(animal_id,tipo_evento_id,responsable_id,fecha_evento,titulo) VALUES(:a,:t,:u,:f,"Examen de laboratorio")');$s->execute(['a'=>$animal,'t'=>$eventType,'u'=>$by,'f'=>$date]);$event=(int)$db->lastInsertId();$s=$db->prepare('INSERT INTO examenes_laboratorio(evento_clinico_id,tipo_examen_id,solicitado_por,fecha_solicitud,fecha_resultado,resultado_resumen,observaciones) VALUES(:e,:t,:u,:f,:fr,:r,:o)');$s->execute(['e'=>$event,'t'=>$type,'u'=>$by,'f'=>$date,'fr'=>!empty($d['fecha_resultado'])?$this->dt($d['fecha_resultado']):null,'r'=>trim((string)($d['resultado_resumen']??''))?:null,'o'=>trim((string)($d['observaciones']??''))?:null]);$id=(int)$db->lastInsertId();if(isset($files['archivo'])&&($files['archivo']['error']??UPLOAD_ERR_NO_FILE)===UPLOAD_ERR_OK){$fid=(new FileService())->store($files['archivo'],$by,'laboratorio');$db->prepare('INSERT INTO examen_laboratorio_archivos(examen_laboratorio_id,archivo_id,descripcion) VALUES(:e,:a,:d)')->execute(['e'=>$id,'a'=>$fid,'d'=>'Resultado / documento']);}(new AuditService())->log($by,$env,'LABORATORIO','CREAR','examenes_laboratorio',$id);return$id;});}
 private function dt(mixed $v):string{if(!$v)return date('Y-m-d H:i:s');$v=str_replace('T',' ',(string)$v);return strlen($v)===16?$v.':00':$v;}
}
